export type LengthType = 'TL' | 'FL' | 'SL'; // Total Length, Fork Length, Standard Length

export interface SpeciesData {
  id: number;
  name: string;
  scientificName: string;
  zone: Zone;
  depthMin: number; // m
  depthMax: number; // m
  avgLengthCm: number;
  avgWeightKg: number;
  maxLengthReportedCm: number;
  gameBaseLengthCm: number;
  gameBaseWeightKg: number;
  gameMinLengthCm: number;
  gameMaxLengthCm: number;
  lengthWeightA: number; // W = A * L^B
  lengthWeightB: number;
  lengthType: LengthType;
  verification: VerificationStatus;
  source: string;
  catchable: boolean;
  observable: boolean;
  protectionStatus: 'none' | 'protected' | 'endangered';
  behavior: string[];
  rarity: number; // 1-10
  sellPriceBase: number; // shells
  bossType?: 'dunkleosteus' | 'megalodon' | 'mosasaurus';
}

