// Zone별 종 수 검증
export function validateSpeciesData(): { valid: boolean; errors: string[] } {
  const errors: string[] = [];
  
  // 총 200종
  if (SPECIES_DATA.length !== 200) {
    errors.push(`Expected 200 species, got ${SPECIES_DATA.length}`);
  }
  
  // ID 중복 검사
  const ids = SPECIES_DATA.map(s => s.id);
  const duplicateIds = ids.filter((id, i) => ids.indexOf(id) !== i);
  if (duplicateIds.length > 0) {
    errors.push(`Duplicate IDs: ${duplicateIds.join(', ')}`);
  }
  
  // 학명 중복 검사
  const names = SPECIES_DATA.map(s => s.scientificName);
  const duplicateNames = names.filter((name, i) => names.indexOf(name) !== i);
  if (duplicateNames.length > 0) {
    errors.push(`Duplicate scientific names: ${duplicateNames.join(', ')}`);
  }
  
  // Zone별 종 수
  const zoneCounts: Record<Zone, number> = { tropical: 0, glacial: 0, volcanic: 0, mangrove: 0, ocean: 0, deepsea: 0 };
  SPECIES_DATA.forEach(s => zoneCounts[s.zone]++);
  
  if (zoneCounts.tropical !== 40) errors.push(`Tropical: expected 40, got ${zoneCounts.tropical}`);
  if (zoneCounts.glacial !== 30) errors.push(`Glacial: expected 30, got ${zoneCounts.glacial}`);
  if (zoneCounts.volcanic !== 30) errors.push(`Volcanic: expected 30, got ${zoneCounts.volcanic}`);
  if (zoneCounts.mangrove !== 35) errors.push(`Mangrove: expected 35, got ${zoneCounts.mangrove}`);
  if (zoneCounts.ocean !== 40) errors.push(`Ocean: expected 40, got ${zoneCounts.ocean}`);
  if (zoneCounts.deepsea !== 25) errors.push(`Deepsea: expected 25, got ${zoneCounts.deepsea}`);
  
  // 길이·무게 범위 검사
  SPECIES_DATA.forEach(s => {
    if (s.gameMinLengthCm <= 0) errors.push(`ID ${s.id}: min length <= 0`);
    if (s.gameMaxLengthCm <= s.gameMinLengthCm) errors.push(`ID ${s.id}: max length <= min length`);
    if (s.gameBaseLengthCm < s.gameMinLengthCm || s.gameBaseLengthCm > s.gameMaxLengthCm) {
      errors.push(`ID ${s.id}: base length out of range`);
    }
  });
  
  return { valid: errors.length === 0, errors };
}

export function getSpeciesById(id: number): SpeciesData | undefined {
  return SPECIES_DATA.find(s => s.id === id);
}

export function getSpeciesByZone(zone: Zone): SpeciesData[] {
  return SPECIES_DATA.filter(s => s.zone === zone);
}

export function getZoneName(zone: Zone): string {
  const names: Record<Zone, string> = {
    tropical: '열대',
    glacial: '빙하',
    volcanic: '화산',
    mangrove: '맹그로브',
    ocean: '대양',
    deepsea: '심해'
  };
  return names[zone];
}
